code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def bands(n, is_blank):
        result = []
        i = 0
        while i < n:
            if is_blank(i):
                i += 1
                continue
            start = i
            while i < n and not is_blank(i):
                i += 1
            result.append((start, i - 1))
        return result

    rb = bands(h, lambda r: all(v == 0 for v in grid[r]))
    cb = bands(w, lambda c: all(grid[r][c] == 0 for r in range(h)))
    centers = {}
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            bg = grid[r0][c0]
            rs, re = r0+1, r1
            cs, ce = c0+1, c1
            vals = [grid[r][c] for r in range(rs,re) for c in range(cs,ce)]
            from collections import Counter
            color, count = Counter(vals).most_common(1)[0]
            if color != bg and count == len(vals):
                centers[ri,ci] = (color, rs, re-1, cs, ce-1)

    # Matching patches in a common tile row/column are joined through blank separators.
    for (ri, ci), a in centers.items():
        color, ar0, ar1, ac0, ac1 = a
        for (rj, cj), b in centers.items():
            if b[0] != color:
                continue
            if rj == ri and cj > ci:
                _, br0, br1, bc0, bc1 = b
                for r in range(max(ar0,br0), min(ar1,br1)+1):
                    for c in range(ac1+1, bc0):
                        if grid[r][c] == 0: out[r][c] = color
            elif cj == ci and rj > ri:
                _, br0, br1, bc0, bc1 = b
                for c in range(max(ac0,bc0), min(ac1,bc1)+1):
                    for r in range(ar1+1, br0):
                        if grid[r][c] == 0: out[r][c] = color
    return out
'''
